import {brands} from './brands.js';
import {credits} from './credits.js';

const main=document.getElementById('main');
const status=document.getElementById('status');
const validIds=new Set(brands.map(b=>b.id));
let selected=[];
try{selected=JSON.parse(localStorage.getItem('sw-compare')||'[]').filter(id=>validIds.has(id)).slice(0,3)}catch{}
let filter='all';
let toastTimer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>brands.find(b=>b.id===id);
const img=(b,n=0,cls='',lazy=true)=>`<img src="assets/${b.id}-${n}.jpg" alt="${esc(b.alt[n])}" class="${cls}" ${lazy?'loading="lazy"':'fetchpriority="high"'} decoding="async">`;
const ext=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
const compareButton=b=>`<button type="button" class="compare-toggle" data-compare="${b.id}" aria-label="${selected.includes(b.id)?'Remove':'Add'} ${esc(b.name)} ${selected.includes(b.id)?'from':'to'} comparison" aria-pressed="${selected.includes(b.id)}">${selected.includes(b.id)?'Added':'Compare'}</button>`;
const field=(label,value,full=false)=>`<div class="fact${full?' full':''}"><dt>${label}</dt><dd>${esc(value)}</dd></div>`;
function announce(message){clearTimeout(toastTimer);status.textContent=message;toastTimer=setTimeout(()=>status.textContent='',3200)}
function persist(){try{localStorage.setItem('sw-compare',JSON.stringify(selected))}catch{}document.getElementById('compare-count').textContent=selected.length||''}
function toggleCompare(id){
 if(selected.includes(id)){selected=selected.filter(x=>x!==id);announce(`${byId(id).name} removed from comparison.`)}
 else if(selected.length<3){selected.push(id);announce(`${byId(id).name} added. ${selected.length} of 3 selected.`)}
 else{announce('Three brands selected. Remove one in Compare to add another.');return}
 persist();
 if(location.hash.startsWith('#compare'))render(false);
 else document.querySelectorAll('[data-compare]').forEach(button=>{const b=byId(button.dataset.compare);button.outerHTML=compareButton(b)});
}
function index(){
 const groups={all:brands,clothing:brands.filter(b=>['bobo','mini','konges','liewood'].includes(b.id)),play:brands.filter(b=>['stapelstein','oli','liewood','konges'].includes(b.id)),home:brands.filter(b=>['oeuf','liewood','nobodinoz','konges'].includes(b.id))};
 const visible=groups[filter]||brands;
 return `<section class="intro"><h1>Children’s lifestyle.<br>Eight distinct worlds.</h1><p>Who they speak to. How they look.<br>What makes each one feel different.</p></section>
 <div class="index-toolbar"><div class="filter-list" role="group" aria-label="Filter brands by category">${[['all','All brands'],['clothing','Clothing'],['play','Play'],['home','Home']].map(([id,label])=>`<button type="button" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><span>${visible.length} brands</span></div>
 <div class="brand-grid">${visible.map((b,i)=>`<article class="brand-entry" data-id="${b.id}"><a class="image-link" href="#brand/${b.id}" aria-label="Explore ${esc(b.name)}">${img(b,0,'',i>3)}</a><div class="entry-heading"><h2><a href="#brand/${b.id}">${b.name}</a></h2>${compareButton(b)}</div><p>${esc(b.short)}</p><div class="entry-meta"><span>${esc(b.category)}</span><a href="#brand/${b.id}">View study</a></div></article>`).join('')}</div>
 <div class="section-end"><p class="note-line">Perception, audiences and archetypes are strategic interpretations, grounded in each brand’s public identity. They are not consumer-research findings.</p><a class="text-link" href="#spectrum">See the spectrum</a></div>`;
}
function miniScale(b){return `<div class="audience-box"><div class="field-label">Communication emphasis</div><div class="mini-scale" role="img" aria-label="${esc(b.audience)}">${[0,1,2,3,4].map(i=>`<span class="${i===b.address?'active':''}"></span>`).join('')}</div><div class="scale-labels"><span>Child’s imagination</span><span>Parent’s priorities</span></div><p class="audience-verdict">${esc(b.verdict)}</p></div>`}
function strategy(b){return `<h2 class="perception">${esc(b.perception)}</h2><p class="reading">${esc(b.reading)}</p><dl class="facts">${field('Brand archetype',b.archetype)}${field('Perceived territory',b.territory)}${field('Target group',b.tg,true)}</dl>${miniScale(b)}<div class="detail-strip"><div><div class="field-label">To the child</div><p>${esc(b.child)}</p></div><div><div class="field-label">To the parent</div><p>${esc(b.parent)}</p></div></div>`}
function identity(b){return `<h2 class="perception">${esc(b.short)}</h2><p class="reading">${esc(b.identity)}</p><dl class="facts">${field('Illustration language',b.illustration,true)}${field('Photography',b.photo,true)}${field('Typography',b.type,true)}</dl><div class="palette" aria-label="Illustrative palette impression">${b.palette.map(([color,name])=>`<div><div class="swatch" style="--swatch:${color}" role="img" aria-label="${name}"></div><span>${name}</span></div>`).join('')}</div><p class="note-line">Palette impression from the imagery; not official brand colour specifications.</p><div class="audience-box"><div class="field-label">Tone of voice · ${b.tone.join(' / ')}</div><p>${esc(b.voiceNote)}</p><p class="voice">${esc(b.voice)}</p><span class="voice-credit">Illustrative line written for this analysis, not a brand quotation.</span></div>`}
function products(b){return `<h2 class="perception">${esc(b.core)}</h2><p class="reading">${esc(b.hero)}</p><div class="field-label">Category range</div><ul class="product-range">${b.range.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><p class="note-line">${esc(b.rangeNote)}</p><dl class="facts" style="margin-top:26px">${field('Perceived market position',b.position,true)}${field('Distinctive mechanism',b.difference,true)}${field('Relative to this set',b.watch,true)}</dl>`}
function profile(id,tab='strategy'){
 const b=byId(id);if(!b)return missing();
 const tabs={strategy:'Perception & audience',identity:'Visual identity',products:'Product world'};
 if(!tabs[tab])tab='strategy';
 const i=brands.indexOf(b),next=brands[(i+1)%brands.length];
 return `<div class="profile-shell"><nav class="brand-nav" aria-label="Brand index">${brands.map(x=>`<a href="#brand/${x.id}" ${x.id===id?'aria-current="page"':''}>${x.name}</a>`).join('')}</nav><article><div class="profile-top"><div><h1>${b.name}</h1><p class="brand-origin">${esc(b.origin)} · ${esc(b.category)}</p></div><div class="profile-actions">${compareButton(b)}${ext(b.sources[0][1],'Brand website')}</div></div><div class="profile-tabs" role="tablist" aria-label="${esc(b.name)} profile sections">${Object.entries(tabs).map(([key,label])=>`<button id="tab-${key}" type="button" data-tab="${key}" data-brand="${b.id}" role="tab" aria-selected="${tab===key}" aria-controls="profile-panel" tabindex="${tab===key?0:-1}">${label}</button>`).join('')}</div><div class="profile-layout"><figure class="profile-image">${img(b,tab==='strategy'?0:1,'',false)}<figcaption>Image © ${b.name}. ${ext(b.sources[b.sources.length-1][1],'Source & collection')}</figcaption></figure><section class="profile-copy" id="profile-panel" role="tabpanel" aria-labelledby="tab-${tab}">${tab==='strategy'?strategy(b):tab==='identity'?identity(b):products(b)}</section></div><div class="profile-bottom"><a href="#sources/${b.id}" class="text-link">Evidence & credits</a><a href="#brand/${next.id}" class="next">Next: ${next.name}</a></div><p class="method-caption">Strategic reading, not measured consumer perception. Product categories checked November 2026; regional assortments vary.</p></article></div>`;
}
function spectrumPanel(key,title,left,right,description){return `<section class="spectrum-panel"><h2>${title}</h2><p>${description}</p><div class="spectrum-head"><span>${left}</span><span>${right}</span></div>${brands.map(b=>`<div class="spectrum-row"><a href="#brand/${b.id}">${b.name}</a><div class="spectrum-track" role="img" aria-label="${esc(key==='address'?b.audience:b.aesthetic)}">${[0,1,2,3,4].map(i=>`<span class="spectrum-slot ${b[key]===i?'selected':''}"></span>`).join('')}</div></div>`).join('')}</section>`}
function spectrum(){return `<div class="spectrum-intro"><h1>Who gets<br>the first word?</h1><p>Playfulness is a visual style.<br>Speaking to a child is a different decision.</p></div><div class="spectrum-grid">${spectrumPanel('address','Audience emphasis','Child’s imagination','Parent’s priorities','The imaginative world a brand foregrounds, not the age of the person paying.')}${spectrumPanel('style','Aesthetic expression','Nostalgic','Expressive','From sentimental and familiar to experimental and graphically assertive. Modern restraint sits between.')}</div><div class="map-notes"><section><h3>The child as protagonist</h3><p>Bobo Choses and Mini Rodini enter the child’s imagination. Their adult appeal comes from sharing that creative point of view.</p></section><section><h3>The parent as curator</h3><p>Oeuf, Nobodinoz, LIEWOOD and Konges Sløjd speak to different adult priorities: design, ease and sentiment.</p></section><section><h3>The object as the bridge</h3><p>Stapelstein and Oli&Carol show why experience and message differ: children play; adults interpret purpose and materials.</p></section></div><div class="section-end"><p class="note-line">Relative editorial placements, not measured scores. All eight rely on adult purchasers. A nostalgic visual world can still be contemporary in product and business model.</p><a href="#compare" class="text-link">Compare the details</a></div>`}
const compareRows=[
 ['Brand perception',b=>esc(b.perception)],['Target group',b=>esc(b.tg)],['Who they address',b=>`<p>${esc(b.audience)}</p><p class="small">${esc(b.verdict)}</p>`],['Archetype',b=>esc(b.archetype)],['Tone',b=>`${b.tone.join(' / ')}<p class="small">${esc(b.voiceNote)}</p>`],['Visual identity',b=>esc(b.identity)],['Illustration',b=>esc(b.illustration)],['Core product',b=>`<p>${esc(b.core)}</p><p class="small">${esc(b.hero)}</p>`],['Category range',b=>b.range.map(esc).join(' · ')],['Market position',b=>esc(b.position)],['What sets it apart',b=>esc(b.difference)]
];
function compare(){const chosen=selected.map(byId);return `<div class="compare-intro"><h1>Side by side.</h1><p>Select up to three brands.<br>Follow the differences across the same lenses.</p></div><fieldset class="brand-picker" aria-label="Choose up to three brands"><legend class="sr-only">Brands to compare</legend>${brands.map(b=>`<label><input type="checkbox" value="${b.id}" data-pick ${selected.includes(b.id)?'checked':''} ${selected.length===3&&!selected.includes(b.id)?'disabled':''}><span>${b.name}</span></label>`).join('')}</fieldset>${chosen.length?`<div class="compare-scroll" role="region" aria-label="Brand comparison table" tabindex="0"><table class="compare-table"><thead><tr><th scope="col"><span class="small muted">${chosen.length} selected</span></th>${chosen.map(b=>`<th scope="col"><a href="#brand/${b.id}">${img(b,0,'compare-img')}${b.name}</a><div class="col-origin">${b.origin}</div></th>`).join('')}</tr></thead><tbody>${compareRows.map(([label,get])=>`<tr><th scope="row">${label}</th>${chosen.map(b=>`<td>${get(b)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<p class="compare-empty">Choose a brand above to start comparing.</p>`}<div class="section-end"><p class="note-line">Target groups, archetypes and market positions are inferred from brand communication, design and category emphasis. “Premium” is a relative strategic reading, not a price audit.</p><a href="#index" class="text-link">Back to the index</a></div>`}
function sources(id){return `<div class="sources-intro"><h1>A reading.<br>With references.</h1><p>Public brand evidence, clearly separated<br>from strategic interpretation.</p></div><div class="source-layout"><section class="method-block"><h2>How to read this study</h2><p>This is a desk-based brand analysis of eight children’s lifestyle businesses, prepared in November 2026. It considers official brand statements, current product navigation and published brand imagery.</p><dl><dt>Verified brand evidence</dt><dd>Product categories, named collections, stated brand philosophies and published imagery are linked to their official sources.</dd><dt>Editorial interpretation</dt><dd>Perception, psychographic target groups, communication emphasis, tone, archetypes and spectrum positions are our strategic reading. They have not been validated through interviews, sales data or audience surveys.</dd><dt>Who is “the audience”?</dt><dd>The child may use the product while the parent buys it. The spectrum describes communication emphasis, not a claim that children are directly targeted with advertising.</dd><dt>Illustrative, not official</dt><dd>Palette impressions are visual cues, not approved brand colour codes. Sample voice lines are newly written examples, not quotations or taglines.</dd><dt>Scope</dt><dd>Category availability varies by region and season. Responsible-production statements are brand-reported; this study is not an independent sustainability audit.</dd><dt>Design reference</dt><dd>The presentation follows the restrained type, neutral surfaces and visible controls of ${ext('https://19-studio.com/','19 studio')} and ${ext('https://npclabs-19.github.io/chocolate-studio/','Chocolate studio')}. Type asset from the supplied Chocolate studio reference.</dd><dt>Image credits</dt><dd>All brand photography and artwork belongs to the respective brands and credited creators. Images are reproduced here as visual references for brand analysis; this site is not affiliated with the featured brands.</dd></dl></section><section aria-label="Sources by brand">${brands.map(b=>`<div class="source-brand" id="source-${b.id}"><h3><a href="#brand/${b.id}">${b.name}</a></h3><div>${b.sources.map(([label,url])=>ext(url,label)).join('')}</div><div class="credits">${ext(credits[b.id+'-0.jpg'],'Original image 1')}${ext(credits[b.id+'-1.jpg'],'Original image 2')}</div><p class="small">Reviewed 4 November 2026 · Official brand sources</p></div>`).join('')}</section></div>`}
function missing(){return `<section class="error-view"><h1>That page isn’t in this study.</h1><p>Explore one of the eight brands from the index.</p><a class="text-link" href="#index">View all brands</a></section>`}
function render(scroll=true){
 const [route,id,tab]=(location.hash.slice(1)||'index').split('/');
 const navRoute=route==='brand'?'index':route;
 document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===navRoute)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 main.innerHTML=route==='index'?index():route==='brand'?profile(id,tab):route==='spectrum'?spectrum():route==='compare'?compare():route==='sources'?sources(id):missing();
 document.title=route==='brand'&&byId(id)?`${byId(id).name} — 19 studio`:`${{index:'Children’s lifestyle',spectrum:'Brand spectrum',compare:'Compare brands',sources:'Sources & method'}[route]||'Brand study'} — 19 studio`;
 if(scroll)window.scrollTo({top:0,behavior:'instant'});
 if(route==='sources'&&id)document.getElementById(`source-${id}`)?.scrollIntoView({block:'center'});
}
document.addEventListener('click',e=>{
 if(e.target.closest('.skip')){e.preventDefault();main.focus();return}
 const comp=e.target.closest('[data-compare]');if(comp){toggleCompare(comp.dataset.compare);return}
 const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render(false);document.querySelector(`[data-filter="${filter}"]`)?.focus();return}
 const tab=e.target.closest('[data-tab]');if(tab){history.replaceState(null,'',`#brand/${tab.dataset.brand}/${tab.dataset.tab}`);render(false);document.getElementById(`tab-${tab.dataset.tab}`)?.focus()}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-pick]')){const id=e.target.value;toggleCompare(id);document.querySelector(`[data-pick][value="${id}"]`)?.focus()}});
document.addEventListener('keydown',e=>{if(e.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[role="tab"]')];let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].click()}});
window.addEventListener('hashchange',()=>render());
persist();render();
